const { test } = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const command = path.join(__dirname, '..', 'bin', 'tipcalc.js');

function run(...args) {
  return spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
}

test('prints the tip and total for a $50 bill at 20 percent', () => {
  const result = run('50', '--percent', '20');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Tip: $10.00  Total: $60.00\n');
  assert.equal(result.stderr, '');
});

test('rounds a half cent up before adding the tip to the bill', () => {
  const result = run('0.05', '--percent', '10');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Tip: $0.01  Total: $0.06\n');
});

test('accepts zero and the percentage boundaries', () => {
  assert.equal(run('0', '--percent', '0').stdout, 'Tip: $0.00  Total: $0.00\n');
  const fullTip = run('0.01', '--percent', '100');
  assert.equal(fullTip.status, 0);
  assert.equal(fullTip.stdout, 'Tip: $0.01  Total: $0.02\n');
});

test('keeps fractional percentages exact', () => {
  const result = run('0.10', '--percent', '5');
  assert.equal(result.stdout, 'Tip: $0.01  Total: $0.11\n');
  assert.equal(run('100', '--percent', '0.125').stdout, 'Tip: $0.13  Total: $100.13\n');
});

test('explains missing or invalid bill and percentage input', () => {
  const cases = [
    { args: [], input: 'bill', correction: 'at most two decimal places' },
    { args: ['50'], input: 'percent', correction: '0 to 100' },
    { args: ['-1', '--percent', '20'], input: 'bill', correction: '0 or more' },
    { args: ['1.001', '--percent', '20'], input: 'bill', correction: 'at most two decimal places' },
    { args: ['abc', '--percent', '20'], input: 'bill', correction: '0 or more' },
    { args: ['50', '--percent', '101'], input: 'percent', correction: '0 to 100' },
    { args: ['50', '--percent', '-1'], input: 'percent', correction: '0 to 100' },
    { args: ['50', '--percent', 'abc'], input: 'percent', correction: '0 to 100' },
  ];

  for (const { args, input, correction } of cases) {
    const result = run(...args);
    assert.equal(result.status, 1, args.join(' '));
    assert.equal(result.stdout, '', args.join(' '));
    assert.match(result.stderr, new RegExp(input, 'i'), args.join(' '));
    assert.match(result.stderr, new RegExp(correction, 'i'), args.join(' '));
  }
});

test('rejects unknown and repeated options', () => {
  for (const args of [
    ['50', '--split', '3', '--percent', '20'],
    ['50', '--percent', '20', '--percent', '30'],
  ]) {
    const result = run(...args);
    assert.equal(result.status, 1);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /Error:/);
  }
});

#!/usr/bin/env node

function parseArguments(args) {
  let bill;
  let percent;

  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === '--percent') {
      if (percent !== undefined) {
        throw new Error('Enter --percent once, with a percentage from 0 to 100.');
      }
      percent = args[++index];
    } else if (argument.startsWith('--')) {
      throw new Error(`Unknown option ${argument}. Use a bill amount and --percent from 0 to 100.`);
    } else if (bill === undefined) {
      bill = argument;
    } else {
      throw new Error('Enter one bill amount, followed by --percent from 0 to 100.');
    }
  }

  if (bill === undefined || !/^[0-9]+(?:\.[0-9]{1,2})?$/.test(bill)) {
    throw new Error('Enter a bill amount of 0 or more with at most two decimal places.');
  }
  if (percent === undefined || !/^[0-9]+(?:\.[0-9]+)?$/.test(percent)) {
    throw new Error('Enter --percent with a percentage from 0 to 100.');
  }

  const [billWhole, billFraction = ''] = bill.split('.');
  const billCents = BigInt(billWhole) * 100n + BigInt(billFraction.padEnd(2, '0') || '0');
  const [percentWhole, percentFraction = ''] = percent.split('.');
  const scale = 10n ** BigInt(percentFraction.length);
  const percentUnits = BigInt(percentWhole) * scale + BigInt(percentFraction || '0');
  if (percentUnits > 100n * scale) {
    throw new Error('Enter --percent with a percentage from 0 to 100.');
  }

  return { billCents, percentUnits, scale };
}

function formatMoney(cents) {
  return `$${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
}

try {
  const { billCents, percentUnits, scale } = parseArguments(process.argv.slice(2));
  const divisor = 100n * scale;
  const tipCents = (billCents * percentUnits * 2n + divisor) / (2n * divisor);
  const totalCents = billCents + tipCents;
  console.log(`Tip: ${formatMoney(tipCents)}  Total: ${formatMoney(totalCents)}`);
} catch (error) {
  console.error(`Error: ${error.message}`);
  process.exitCode = 1;
}

